apply:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /posts/{postId} {
      allow read, delete: if request.auth != null && request.auth.uid == resource.data.author_uid;
      allow create: if request.auth != null && request.auth.uid == request.resource.data.author_uid;
      allow update: if request.auth != null
        && request.auth.uid == resource.data.author_uid
        && request.auth.uid == request.resource.data.author_uid;
    }
  }
}
